{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "direction",
      "type": "'vertical' | 'horizontal' | 'horizontal-labels'",
      "description": "Controls field arrangement. Vertical stacks top-to-bottom, horizontal uses one fractional grid track per field in logical inline order, and horizontal-labels uses CSS Grid with labels beside inputs on the inline-start side (collapsing to vertical when the viewport is <=480px).",
      "default": "'vertical'"
    },
    {
      "name": "defaultOptionality",
      "type": "'optional' | 'required'",
      "description": "The state the form treats as its default, so only the exception shows an optional/required indicator. With \"optional\", only fields marked isRequired show an indicator; with \"required\", only fields marked isOptional do. A field that restates the default shows nothing. Under \"required\" the unmarked fields also expose aria-required so screen readers match the visual default; aria-required only, never the native required attribute. CheckboxInput, Switch and CheckboxList are the exception: an unchecked box, an off switch or an empty group is an answer, so they take no required state from the default. A CheckboxInput or Switch is required only through its own isRequired. Leave unset for today's per-field behavior."
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Form fields to arrange. Accepts Astryx inputs (TextInput, Selector, etc.) and Field-wrapped custom controls."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
